def evidence_review(revision,records):
    # Own exact evidence matrix. It records claims,does not authenticate test reports.
    required=("schema","math-reference","integration","mobile","accessibility","durable-recovery")
    source_only=frozenset(required[:3])
    if type(revision) is not str or not 1<=len(revision)<=32 or not revision.isascii() or not revision.isalnum():raise ValueError("invalid revision")
    if type(records) is not list or len(records)>len(required):raise ValueError("invalid evidence records")
    seen={}
    for row in records:
        if type(row) is not tuple or len(row)!=3:raise ValueError("invalid evidence row")
        gate,rev,state=row
        if type(gate) is not str or gate not in required or gate in seen or type(rev) is not str or type(state) is not str or state not in ("passed","failed","unverified"):
            raise ValueError("invalid duplicate or unknown evidence")
        seen[gate]=(rev,state)
    status=tuple((gate,seen[gate][1] if gate in seen and seen[gate][0]==revision else "unverified") for gate in required)
    source_ready=all(state=="passed" for gate,state in status if gate in source_only)
    held=tuple(gate for gate,state in status if state!="passed")
    return {"revision":revision,"gate_status":status,"source_ready":source_ready,"all_listed_gates_passed":not held,"held_gates":held}

records=[("schema","r1","passed"),("math-reference","r1","passed"),("integration","r1","passed"),("mobile","old","passed")]
a=evidence_review("r1",records)
print(a["source_ready"],a["all_listed_gates_passed"])
print(a["held_gates"])
print(evidence_review("r2",records)["source_ready"])
try:evidence_review("r1",records+[records[0]])
except ValueError as error:print(error)
